<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api/admin';import{session}from'../api/http';
const rows=ref<any[]>([]),users=ref<any[]>([]),visible=ref(false),editing=ref<any>();const isAdmin=computed(()=>session()?.role==='ADMIN');
const blank=()=>({channelCode:'',channelName:'',channelType:'ORGANIZATION',parentChannelId:null,contactName:'',contactPhone:'',cooperationStatus:'ACTIVE',settlementInfo:'',ownerUserId:null});const form=reactive<any>(blank());
async function load(){try{rows.value=await api.channels()as any[];if(isAdmin.value)users.value=await api.users()as any[]}catch(e:any){ElMessage.error(e.message)}}
function open(row?:any){editing.value=row;Object.assign(form,blank(),row||{});visible.value=true}
async function save(){try{editing.value?await api.updateChannel(editing.value.id,form):await api.createChannel(form);ElMessage.success('统一渠道档案已保存');visible.value=false;load()}catch(e:any){ElMessage.error(e.message)}}
function typeLabel(value:string){return({RESOURCE:'资源渠道',ORGANIZATION:'机构渠道',ENTERPRISE:'企业渠道',SALES_AGENT:'销售代理'}as Record<string,string>)[value]||value}
function statusLabel(value:string){return({PENDING:'待合作',ACTIVE:'合作中',SUSPENDED:'已暂停',ENDED:'已结束'}as Record<string,string>)[value]||value}
onMounted(load);
</script>
<template><div class="page"><div class="page-heading"><div><h1>渠道档案</h1><p>客户归属、渠道订单和佣金统一使用同一个渠道ID；旧二级渠道表只读保留。</p></div><el-button v-if="isAdmin" type="primary" @click="open()">新增渠道</el-button></div><div class="table-card"><el-table :data="rows"><el-table-column prop="channelCode" label="渠道编码" min-width="150"/><el-table-column prop="channelName" label="渠道名称" min-width="170"/><el-table-column label="渠道类型" width="110"><template #default="s">{{typeLabel(s.row.channelType)}}</template></el-table-column><el-table-column label="上级渠道" min-width="140"><template #default="s">{{rows.find(x=>x.id===s.row.parentChannelId)?.channelName||'-'}}</template></el-table-column><el-table-column prop="contactName" label="联系人" width="100"/><el-table-column prop="contactPhone" label="联系方式" min-width="135"/><el-table-column label="合作状态" width="105"><template #default="s"><el-tag :type="s.row.cooperationStatus==='ACTIVE'?'success':s.row.cooperationStatus==='PENDING'?'warning':'info'">{{statusLabel(s.row.cooperationStatus)}}</el-tag></template></el-table-column><el-table-column label="负责人" min-width="110"><template #default="s">{{users.find(x=>x.id===s.row.ownerUserId)?.displayName||'-'}}</template></el-table-column><el-table-column prop="settlementInfo" label="结算信息" min-width="190"/><el-table-column v-if="isAdmin" label="操作" width="90" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" :title="editing?'编辑渠道':'新增渠道'" width="760"><el-form label-position="top"><el-row :gutter="18"><el-col :span="12"><el-form-item label="渠道编码"><el-input v-model="form.channelCode" :disabled="!!editing"/></el-form-item></el-col><el-col :span="12"><el-form-item label="渠道名称"><el-input v-model="form.channelName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="渠道类型"><el-select v-model="form.channelType" style="width:100%"><el-option label="资源渠道" value="RESOURCE"/><el-option label="机构渠道" value="ORGANIZATION"/><el-option label="企业渠道" value="ENTERPRISE"/><el-option label="销售代理" value="SALES_AGENT"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="上级渠道"><el-select v-model="form.parentChannelId" clearable style="width:100%"><el-option v-for="item in rows.filter(x=>x.id!==editing?.id)" :key="item.id" :label="item.channelName" :value="item.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="联系人"><el-input v-model="form.contactName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="联系方式"><el-input v-model="form.contactPhone"/></el-form-item></el-col><el-col :span="12"><el-form-item label="合作状态"><el-select v-model="form.cooperationStatus" style="width:100%"><el-option label="待合作" value="PENDING"/><el-option label="合作中" value="ACTIVE"/><el-option label="已暂停" value="SUSPENDED"/><el-option label="已结束" value="ENDED"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="内部负责人"><el-select v-model="form.ownerUserId" clearable style="width:100%"><el-option v-for="item in users.filter(x=>x.status==='ENABLED')" :key="item.id" :label="item.displayName" :value="item.id"/></el-select></el-form-item></el-col><el-col :span="24"><el-form-item label="结算信息"><el-input v-model="form.settlementInfo" type="textarea"/></el-form-item></el-col></el-row></el-form><template #footer><div class="dialog-footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></div></template></el-dialog></div></template>

